def net_area(phone: str) -> tuple[str, str] | None:
    """Return the longest valid Dutch geographic prefix and its primary place."""
    for prefix in sorted(NET_AREAS, key=len, reverse=True):
        if phone.startswith(prefix):
            return prefix, NET_AREAS[prefix]
    return None
